def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_x_squared(x):
    if x == 1:
        return 1
    factors = prime_factorization(x)
    tau = 1
    for prime, exponent in factors.items():
        # If x = p^a, then x^2 = p^(2a). tau(x^2) = 2a + 1
        tau *= (2 * exponent + 1)
    return tau

test_cases = [1, 2, 3, 4, 5, 6, 12]
results = {}
for x in test_cases:
    result = tau_x_squared(x)
    results[x] = result

print(results)
